#!/usr/bin/env python3
"""Declared whole original/actual Metal Blood public-spray comparison."""
import argparse,json
from pathlib import Path
from PIL import Image,ImageDraw
from speed_profile_contract import sha
SELECTED=(1,3,6,16,30,40,50,57,58,59,60,90)
def run(native,metal,output):
 output.mkdir(parents=True,exist_ok=False);n=json.loads((native/'manifest.json').read_text());m=json.loads((metal/'manifest.json').read_text());assert n['initialization']['parameters']==[40,224,3,5,5,1]and n['initialization']['map_ambient']==52;assert m['status']=='pass'and len(m['frames'])==90 and m['sample_simulation_ticks']==list(range(1,91));whole=Image.new('RGB',(1280,len(SELECTED)*505));crop=Image.new('RGB',(320,len(SELECTED)*185));w=ImageDraw.Draw(whole);c=ImageDraw.Draw(crop);pairs=[]
 for row,tick in enumerate(SELECTED):
  a=n['rows'][tick-1];p=[Path(a['image']),Path(m['frames'][tick-1]['path'])];h=[a['image_sha256'],m['frames'][tick-1]['sha256']];assert[sha(x.read_bytes())for x in p]==h;images=[Image.open(x).convert('RGB')for x in p];boxes=[im.getbbox()for im in images];pairs.append(dict(tick=tick,images=list(map(str,p)),sha256=h,visible_bbox=boxes,native_draws=len(a['draws']),owner_flags=a['owner_flags'],done=a['done'],nearzero_residual=tick==58))
  for col,(im,label)in enumerate(zip(images,('Original','Actual Metal'))):whole.paste(im,(col*640,row*505+25));w.text((col*640+4,row*505+5),f'{label} Blood tick{tick}',fill='white');crop.paste(im.crop((260,230,420,390)),(col*160,row*185+25));c.text((col*160+4,row*185+5),f'{label} tick{tick}',fill='white')
 whole.save(output/'whole.png');crop.save(output/'fixed-crop.png');r=dict(status='awaiting_independent_review',accepted=False,type_id='0xddc4042e',binary_sha256=m['binary_sha256'],native_manifest_sha256=sha((native/'manifest.json').read_bytes()),metal_manifest_sha256=sha((metal/'manifest.json').read_bytes()),whole_sha256=sha((output/'whole.png').read_bytes()),fixed_crop_sha256=sha((output/'fixed-crop.png').read_bytes()),pairs=pairs,actual_frames=90,pixel_summary={k:v for k,v in m['pixel_summary'].items()if k!='pixel_sha256'},configuration=m['scenario'],appearance_fitted=False,scope='Exact registeredMisc/Blood.I3D genuineclass/publicSetParams/fullInit/Animate/PreRender/Render versus actualMetal, declarationActorAcolyte0,0,16/effect0,0,56; publicspray40,224,3,5,5,1/commonInitCRTseed2/detail4; originalMapAmbient32withGamma4→raw52/white, normalrenderer38/dir1; all8authoredquads andtwointerleavedpasses. Controllerfly→splat→shrink andoriginalkill60/blank90. Samefull640x480/camera320,320/fixedcrop260,230,420,390. Actualsourcefield/matrix/RNG/color andwholebodyadmission proofs separate. GenericTObjectInstancePulse4708e0 map/world callback explicitly isolated; mapinsertion/damage/naturalcaster/audio/device/exactpixels notclaimed. ≤1pxsampling/bounds andnearzero58nativeblank/Metal1pixel remainopen; nofitting.');(output/'manifest.json').write_text(json.dumps(r,indent=2)+'\n');print(r['status'],r['pixel_summary']);return r
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--native',type=Path,required=True);p.add_argument('--metal',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();run(a.native,a.metal,a.output)
